algorithms.pseudocode:
if instruction writes logical register R:
  RegisterDigestTable[R].valid = 0
  RegisterDigestTable[R].payload = ROB_index

if T == INT:
  t_cnt = count_trailing_zeros_or_ones(V) & 0x3F
  l_cnt = count_leading_zeros_or_ones(V) & 0x3F
  val_6 = V & 0x3F
  return t_cnt ^ (l_cnt << 3) ^ (val_6 << 6)
else if T == FP:
  class = classify_fp(V)
  if class == FP64: return (sign(V) << 11) | (exp_FP64(V)[7:0] << 3)
  else if class == FP32: return (sign(V) << 8) | (exp_FP32(V)[4:0] << 3)
  else if class == FP16: return (sign(V) << 5) | (exp_FP16(V)[1:0] << 3)
else if T == FLAG:
  return (V[3:0] << 8) | (V[3:0] << 4) | V[3:0]

for R in 0..64:
  if RegisterDigestTable[R].decay_ctr > 0:
    RegisterDigestTable[R].decay_ctr -= 1
    if RegisterDigestTable[R].decay_ctr == 0:
      RegisterDigestTable[R].valid = 0

for bank in 0..7:
  valid_regs = {r | r % 8 == bank and RegisterDigestTable[r].valid at prediction_time}
  if valid_regs is not empty:
    target_r = random_choice(valid_regs)
    digest = RegisterDigestTable[target_r].payload
    update_WT(bank, target_r, digest, PC, outcome)
    update_UT(target_r, PC, outcome == WT_pred_for_target_r)
